:root {
  --card-bg: #1a3a5c;
  --header-bg: #0f2540;
  --accent: #f0a500;
  --accent-light: #ffd166;
  --text-primary: #ffffff;
  --text-muted: #8ab4d4;
  --stamp-filled-bg: #0e4f7a;
  --stamp-empty-bg: #122d47;
  --badge-bg: #f0a500;
  --badge-text: #0f2540;
  --footer-bg: #0f2540;
  --border-color: #2a5580;
}

.stamp-card {
  background-color: var(--card-bg);
  border-radius: 16px;
  border: 2px solid var(--border-color);
  width: 380px;
  overflow: hidden;
  margin: 0 auto;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 18px;
}

.brand-icon {
  font-size: 28px;
  line-height: 1;
}

.brand-info {
  flex: 1;
}

.brand-name {
  font-size: 17px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0;
  line-height: 1.2;
}

.card-sub {
  font-size: 11px;
  color: var(--text-muted);
  margin: 0;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 800;
  padding: 4px 10px;
  border-radius: 20px;
  letter-spacing: 0.1em;
}

.stamps {
  display: flex;
  gap: 10px;
  padding: 22px 18px;
  justify-content: center;
}

.stamp {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin: 0;
  border: 2px solid var(--border-color);
}

.stamp.filled {
  background-color: var(--stamp-filled-bg);
  border-color: var(--accent);
}

.stamp.empty {
  background-color: var(--stamp-empty-bg);
  border-color: var(--border-color);
}

.card-footer {
  background-color: var(--footer-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
}

.progress-label {
  font-size: 12px;
  color: var(--accent-light);
  font-weight: 600;
}

.expiry {
  font-size: 11px;
  color: var(--text-muted);
}
